const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const volcano = ee.Geometry.Point([160.64, 56.06]);
  const date = '2025-08-08';

  // Define regions to check plume direction (east, west, north, south of volcano)
  const eastRegion = ee.Geometry.Rectangle([160.64, 55.8, 162.0, 56.3]);
  const westRegion = ee.Geometry.Rectangle([159.0, 55.8, 160.64, 56.3]);
  const northRegion = ee.Geometry.Rectangle([160.3, 56.06, 160.98, 56.5]);
  const southRegion = ee.Geometry.Rectangle([160.3, 55.5, 160.98, 56.06]);

  // 2. Data Acquisition - Try Sentinel-2 first
  let collection = ee.ImageCollection('COPERNICUS/S2_HARMONIZED')
    .filterBounds(volcano)
    .filterDate(date, ee.Date(date).advance(1, 'day'));

  let collectionSize = await collection.size().getInfo();
  console.log(`Sentinel-2 images found: ${collectionSize}`);

  // If no Sentinel-2, try MODIS Terra
  if (collectionSize === 0) {
    console.log('Trying MODIS Terra...');
    collection = ee.ImageCollection('MODIS/061/MOD09GA')
      .filterBounds(volcano)
      .filterDate(date, ee.Date(date).advance(1, 'day'));

    collectionSize = await collection.size().getInfo();
    console.log(`MODIS Terra images found: ${collectionSize}`);
  }

  if (collectionSize === 0) {
    console.log('No imagery available for this date and location.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Use Aerosol Index to detect ash plume
  const image = collection.first();

  // For Sentinel-2, calculate aerosol optical thickness proxy using blue/red ratio
  const aerosol = image.select('B1').divide(image.select('B4'));

  // Calculate mean aerosol values in each direction
  const eastStats = await aerosol.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: eastRegion,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const westStats = await aerosol.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: westRegion,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const northStats = await aerosol.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: northRegion,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const southStats = await aerosol.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: southRegion,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const eastMean = eastStats.B1_mean;
  const westMean = westStats.B1_mean;
  const northMean = northStats.B1_mean;
  const southMean = southStats.B1_mean;

  console.log(`East aerosol index: ${eastMean !== null ? eastMean.toFixed(3) : 'null'}`);
  console.log(`West aerosol index: ${westMean !== null ? westMean.toFixed(3) : 'null'}`);
  console.log(`North aerosol index: ${northMean !== null ? northMean.toFixed(3) : 'null'}`);
  console.log(`South aerosol index: ${southMean !== null ? southMean.toFixed(3) : 'null'}`);

  // 4. Validation & Final Answer
  if (eastMean === null && westMean === null && northMean === null && southMean === null) {
    console.log('Cannot calculate aerosol index - no valid pixels.');
    console.log('<answer>C2</answer>');
    return;
  }

  // Determine primary direction based on highest aerosol index
  const directions = {
    'East': eastMean || 0,
    'West': westMean || 0,
    'North': northMean || 0,
    'South': southMean || 0
  };

  const maxDirection = Object.keys(directions).reduce((a, b) => directions[a] > directions[b] ? a : b);
  console.log(`Primary plume direction: ${maxDirection} (index: ${directions[maxDirection].toFixed(3)})`);

  if (maxDirection === 'East' && directions['East'] > directions['West'] * 1.2) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
